use xiom.io;

use xiom.string;
type Person = {
  name: Str;
  age: Int;
}

fn is_older(a: Person, b: Person) -> Bool {
  return a.age > b.age;
}

fn same_age(a: Person, b: Person) -> Bool {
  return a.age == b.age;
}

fn has_longer_name(a: Person, b: Person) -> Bool {
  return string.str_len(a.name) > string.str_len(b.name);
}

fn main() -> Int {
  let p1 = Person{ name: "Oliver", age: 16 };
  let p2 = Person{ name: "Pat", age: 14 };
  io.println(is_older(p1, p2).to_str());
  io.println(same_age(p1, p2).to_str());
  io.println(has_longer_name(p1, p2).to_str());
  return 0;
}
